#include "json_report.hpp"

#include <cstdlib>
#include <string>

#include "json_writer.hpp"
#include "sha256.hpp"

namespace mfs {
namespace {

// Finds "key": value at the top level of an object. The report is generated by
// this project, so a small targeted scan is enough; it is not a general parser.
bool find_number(const std::string& json, const std::string& key, double& out) {
  const std::string needle = "\"" + key + "\"";
  size_t pos = json.find(needle);
  if (pos == std::string::npos) {
    return false;
  }
  pos = json.find(':', pos + needle.size());
  if (pos == std::string::npos) {
    return false;
  }
  const char* begin = json.c_str() + pos + 1;
  char* end = nullptr;
  const double value = std::strtod(begin, &end);
  if (end == begin) {
    return false;
  }
  out = value;
  return true;
}

}  // namespace

std::string report_json(const RepairResult& result,
                        const PipelineOptions& options) {
  JsonWriter json;
  json.begin_object();
  json.field("format_version", static_cast<uint32_t>(1));
  json.field("segment_frames", options.segment_frames);
  json.field("time_base",
             std::to_string(options.index_time_base.num) + "/" +
                 std::to_string(options.index_time_base.den));

  json.begin_object("metrics");
  json.field("roundtrip_match_rate", result.roundtrip_match_rate);
  json.field("keyframe_index_hit_rate", result.keyframe_index_hit_rate);
  json.field("segment_hash_match_rate", result.segment_hash_match_rate);
  json.end_object();

  json.begin_object("counts");
  json.field("repaired_frames", result.repaired_frames);
  json.field("duplicate_packets", result.duplicate_packets);
  json.field("lost_ranges", result.lost_ranges);
  json.field("decode_errors", result.decode_errors);
  json.field("first_error_offset", result.first_error_offset);
  json.field("packets_read", result.packets_read);
  json.field("packets_accepted", result.packets_accepted);
  json.field("out_of_window_packets", result.out_of_window_packets);
  json.field("checksum_errors", result.checksum_errors);
  json.field("truncated_records", result.truncated_records);
  json.field("input_bytes", result.input_bytes);
  json.field("truncated_input", result.truncated_input);
  json.end_object();

  json.begin_object("timestamps");
  json.field("wrap_fixes", result.timestamps.wrap_fixes);
  json.field("duplicate_timestamps", result.timestamps.duplicate_timestamps);
  json.field("backward_timestamps", result.timestamps.backward_timestamps);
  json.field("missing_timestamps", result.timestamps.missing_timestamps);
  json.field("drift_fixes", result.timestamps.drift_fixes);
  json.field("nominal_interval_us", result.timestamps.nominal_interval_us);
  json.field("strictly_increasing", result.timestamps.strictly_increasing);
  json.end_object();

  json.field("roundtrip_checked", result.roundtrip_checked);
  json.field("empty_sequence", result.empty_sequence);
  json.field("index_queries", result.index_queries);
  json.field("index_hits", result.index_hits);

  json.begin_array("segments");
  for (const IndexEntry& entry : result.index) {
    json.begin_object();
    json.field("segment_id", entry.segment_id);
    json.field("keyframe_seq", entry.keyframe_seq);
    json.field("start_ts_us", entry.start_ts_us);
    json.field("end_ts_us", entry.end_ts_us);
    json.field("pts", entry.pts);
    json.field("time_base",
               std::to_string(entry.time_base.num) + "/" +
                   std::to_string(entry.time_base.den));
    json.field("frame_count", entry.frame_count);
    json.field("source_offset", entry.source_offset);
    json.hex_field("sha256", entry.segment_sha256);
    json.end_object();
  }
  json.end_array();

  json.begin_array("lost_ranges");
  for (const LostRange& range : result.lost) {
    json.begin_object();
    json.field("first_seq", range.first_seq);
    json.field("last_seq", range.last_seq);
    json.field("estimated_start_us", range.estimated_start_us);
    json.field("estimated_end_us", range.estimated_end_us);
    json.field("estimated_frames", range.estimated_frames);
    json.end_object();
  }
  json.end_array();

  json.begin_array("errors");
  for (const RepairError& error : result.errors) {
    json.begin_object();
    json.field("type", to_string(error.type));
    json.field("offset", error.offset);
    json.field("record_index", error.record_index);
    json.field("detail", error.detail);
    json.end_object();
  }
  json.end_array();

  json.begin_array("frames");
  for (const RepairedFrame& frame : result.frames) {
    json.begin_object();
    json.field("seq", frame.seq);
    json.field("ts_us", frame.ts_us);
    json.field("original_ts_us", frame.original_ts_us);
    json.field("keyframe", frame.keyframe);
    json.field("decoded", frame.decoded);
    json.field("source_offset", frame.source_offset);
    json.hex_field("sha256", frame.frame_sha256);
    json.end_object();
  }
  json.end_array();

  json.end_object();
  return json.str();
}

bool parse_report_metrics(const std::string& json, ReportMetrics& out) {
  ReportMetrics parsed;
  double number = 0.0;
  if (!find_number(json, "roundtrip_match_rate", number)) {
    return false;
  }
  parsed.roundtrip_match_rate = number;
  if (!find_number(json, "keyframe_index_hit_rate", number)) {
    return false;
  }
  parsed.keyframe_index_hit_rate = number;
  if (!find_number(json, "segment_hash_match_rate", number)) {
    return false;
  }
  parsed.segment_hash_match_rate = number;
  if (find_number(json, "repaired_frames", number)) {
    parsed.repaired_frames = static_cast<uint64_t>(number);
  }
  if (find_number(json, "duplicate_packets", number)) {
    parsed.duplicate_packets = static_cast<uint64_t>(number);
  }
  if (find_number(json, "lost_ranges", number)) {
    parsed.lost_ranges = static_cast<uint64_t>(number);
  }
  if (find_number(json, "decode_errors", number)) {
    parsed.decode_errors = static_cast<uint64_t>(number);
  }
  if (find_number(json, "first_error_offset", number)) {
    parsed.first_error_offset = static_cast<int64_t>(number);
  }
  out = parsed;
  return true;
}

}  // namespace mfs
